290	// Helper function to add a node to a directory
291	int add_to_directory(FileNode* dir, const char* name, FileNode* node) {
292	    if (dir->type != FILE_TYPE_DIRECTORY) {
293	        return -ENOTDIR;
294	    }
295	    
296	    // Check if a file with this name already exists
297	    for (size_t i = 0; i < dir->num_entries; i++) {
298	        if (strcmp(dir->entries[i].name, name) == 0) {
299	            return -EEXIST;
300	        }
301	    }
302	    
303	    // Expand the directory if needed
304	    if (dir->num_entries >= dir->max_entries) {
305	        size_t new_max = dir->max_entries * 2;
306	        DirEntry* new_entries = (DirEntry*)realloc(dir->entries, new_max * sizeof(DirEntry));
307	        if (new_entries == NULL) {
308	            return -ENOMEM;
309	        }
310	        dir->entries = new_entries;
311	        dir->max_entries = new_max;
312	    }
313	    
314	    // Add the new entry
315	    strncpy(dir->entries[dir->num_entries].name, name, MAX_PATH_LENGTH);
316	    dir->entries[dir->num_entries].name[MAX_PATH_LENGTH - 1] = '\0';
317	    dir->entries[dir->num_entries].node = node;
318	    dir->num_entries++;
319	    
320	    // Update directory modification time
321	    dir->modified = time(NULL);
322	    
323	    return 0;
324	}
