442	// SYS_open: Open a file
443	int sys_open(const char* pathname, int flags, mode_t mode) {
444	    if (root == NULL) {
445	        init_filesystem();
446	    }
447	    
448	    FileNode* parent_dir = NULL;
449	    FileNode* node = find_node(pathname, &parent_dir);
450	    
451	    if (node == NULL) {
452	        // File not found
453	        if (flags & O_CREAT) {
454	            // Create a new file
455	            char dir_path[MAX_PATH_LENGTH];
456	            char filename[MAX_PATH_LENGTH];
457	            
458	            split_path(pathname, dir_path, filename);
459	            
460	            if (strlen(filename) == 0) {
461	                return -EINVAL; // Invalid filename
462	            }
463	            
464	            if (parent_dir == NULL) {
465	                parent_dir = find_node(dir_path, NULL);
466	                if (parent_dir == NULL) {
467	                    return -ENOENT; // Parent directory not found
468	                }
469	            }
470	            
471	            if (parent_dir->type != FILE_TYPE_DIRECTORY) {
472	                return -ENOTDIR;
473	            }
474	            
475	            node = create_node(filename, FILE_TYPE_REGULAR, parent_dir);
476	            int result = add_to_directory(parent_dir, filename, node);
477	            if (result < 0) {
478	                free(node);
479	                return result;
480	            }
481	        } else {
482	            return -ENOENT; // File not found and we're not creating it
483	        }
484	    } else if (flags & O_CREAT && flags & O_EXCL) {
485	        return -EEXIST; // File exists but O_CREAT|O_EXCL was specified
486	    }
487	    
488	    if (node->type == FILE_TYPE_DIRECTORY && (flags & O_WRONLY || flags & O_RDWR)) {
489	        return -EISDIR; // Cannot open directory for writing
490	    }
491	    
492	    if (flags & O_TRUNC && (flags & O_WRONLY || flags & O_RDWR)) {
493	        // Truncate the file
494	        if (node->data != NULL) {
495	            free(node->data);
496	            node->data = NULL;
497	        }
498	        node->size = 0;
499	        node->capacity = 0;
500	        node->modified = time(NULL);
501	    }
502	    
503	    int fd = allocate_fd(node, flags);
504	    if (fd < 0) {
505	        return fd;
506	    }
507	    
508	    if (flags & O_APPEND) {
509	        fd_table[fd].position = node->size;
510	    } else {
511	        fd_table[fd].position = 0;
512	    }
513	    
514	    node->accessed = time(NULL);
515	    
516	    return fd;
517	}
