529	// SYS_lseek: Reposition read/write file offset
530	off_t sys_lseek(int fd, off_t offset, int whence) {
531	    if (fd < 0 || fd >= MAX_FILE_DESCRIPTORS || !fd_table[fd].used) {
532	        return -EBADF;
533	    }
534	    
535	    FileNode* node = fd_table[fd].node;
536	    off_t new_pos = 0;
537	    
538	    switch (whence) {
539	        case SEEK_SET:
540	            new_pos = offset;
541	            break;
542	        case SEEK_CUR:
543	            new_pos = fd_table[fd].position + offset;
544	            break;
545	        case SEEK_END:
546	            new_pos = node->size + offset;
547	            break;
548	        default:
549	            return -EINVAL;
550	    }
551	    
552	    if (new_pos < 0) {
553	        return -EINVAL;
554	    }
555	    
556	    fd_table[fd].position = new_pos;
557	    return new_pos;
558	}
