768	// Main syscall handler
769	long syscall_fs(int syscall_num, ...) {
770	    va_list args;
771	    va_start(args, syscall_num);
772	    long ret = 0;
773	    
774	    switch (syscall_num) {
775	        case SYS_read: {
776	            int fd = va_arg(args, int);
777	            void* buf = va_arg(args, void*);
778	            size_t count = va_arg(args, size_t);
779	            ret = sys_read(fd, buf, count);
780	            break;
781	        }
782	        case SYS_write: {
783	            int fd = va_arg(args, int);
784	            const void* buf = va_arg(args, const void*);
785	            size_t count = va_arg(args, size_t);
786	            ret = sys_write(fd, buf, count);
787	            break;
788	        }
789	        case SYS_open: {
790	            const char* pathname = va_arg(args, const char*);
791	            int flags = va_arg(args, int);
792	            mode_t mode = va_arg(args, mode_t);
793	            ret = sys_open(pathname, flags, mode);
794	            break;
795	        }
796	        case SYS_close: {
797	            int fd = va_arg(args, int);
798	            ret = sys_close(fd);
799	            break;
800	        }
801	        case SYS_lseek: {
802	            int fd = va_arg(args, int);
803	            off_t offset = va_arg(args, off_t);
804	            int whence = va_arg(args, int);
805	            ret = sys_lseek(fd, offset, whence);
806	            break;
807	        }
808	        case SYS_fsync: {
809	            int fd = va_arg(args, int);
810	            ret = sys_fsync(fd);
811	            break;
812	        }
813	        case SYS_rename: {
814	            const char* oldpath = va_arg(args, const char*);
815	            const char* newpath = va_arg(args, const char*);
816	            ret = sys_rename(oldpath, newpath);
817	            break;
818	        }
819	        case SYS_mkdir: {
820	            const char* pathname = va_arg(args, const char*);
821	            mode_t mode = va_arg(args, mode_t);
822	            ret = sys_mkdir(pathname, mode);
823	            break;
824	        }
825	        case SYS_unlink: {
826	            const char* pathname = va_arg(args, const char*);
827	            ret = sys_unlink(pathname);
828	            break;
829	        }
830	        default:
831	            ret = -EINVAL; // Invalid system call
832	    }
833	    
834	    va_end(args);
835	    return ret;
836	}

