  1469	// Helper function for strtok: returns the length of the initial segment of str 
  1470	// which consists entirely of characters not in reject
  1471	size_t strcspn(const char* str, const char* reject) {
  1472	    size_t count = 0;
  1473	    
  1474	    while (*str) {
  1475	        if (strchr(reject, *str) != NULL) {
  1476	            return count;
  1477	        }
  1478	        str++;
  1479	        count++;
  1480	    }
  1481	    
  1482	    return count;
  1483	}
  1484	
  1485	// Helper function for strtok: returns the length of the initial segment of str 
  1486	// which consists entirely of characters in accept
  1487	size_t strspn(const char* str, const char* accept) {
  1488	    size_t count = 0;
  1489	    
  1490	    while (*str && strchr(accept, *str) != NULL) {
  1491	        str++;
  1492	        count++;
  1493	    }
  1494	    
  1495	    return count;
  1496	}
