  1498	char* strncat(char* dest, const char* src, size_t n) {
  1499	    size_t dest_len = strlen(dest);
  1500	    size_t i;
  1501	    
  1502	    for (i = 0; i < n && src[i] != '\0'; i++) {
  1503	        dest[dest_len + i] = src[i];
  1504	    }
  1505	    dest[dest_len + i] = '\0';
  1506	    
  1507	    return dest;
  1508	}
