  1519	/* 
  1520	 * Generic syscall function that can handle up to 6 arguments
  1521	 * Returns the syscall return value (usually negative on error)
  1522	 * 
  1523	 * Arguments are passed in the following registers:
  1524	 * syscall number: rax
  1525	 * arg1: rdi
  1526	 * arg2: rsi
  1527	 * arg3: rdx
  1528	 * arg4: r10
  1529	 * arg5: r8
  1530	 * arg6: r9
  1531	 */
  1532	
  1533	static long syscall6(long syscall_num, long arg1, long arg2, long arg3, 
  1534	                     long arg4, long arg5, long arg6) {
  1535	    long result;
  1536	
  1537	    /* Special case for stdout/stderr writes - bypass fake filesystem */
  1538	    if (syscall_num == SYS_write && (arg1 == 0 || arg1 == 1)) {
  1539	        /* Use the real syscall for stdout/stderr */
  1540	      return real_syscall6(syscall_num, arg1, arg2, arg3, arg4, arg5, arg6);
  1541	    }
  1542	
  1543	    /* Check if this is a file-related syscall that should be handled by fake_fs.c */
  1544	    switch (syscall_num) {
  1545	        case SYS_read:
  1546	        case SYS_write:
  1547	        case SYS_open:
  1548	        case SYS_close:
  1549	        case SYS_lseek:
  1550	        case SYS_fsync:
  1551	        case SYS_rename:
  1552	        case SYS_mkdir:
  1553	        case SYS_unlink:
  1554		  #ifdef USE_FS
  1555		  /* Redirect to the fake filesystem handler */
  1556		  return syscall_fs((int)syscall_num, arg1, arg2, arg3, arg4, arg5, arg6);
  1557		  #else
  1558		  0;
  1559		  #endif
  1560		  
  1561	    }
  1562	
  1563	    return real_syscall6(syscall_num, arg1, arg2, arg3, arg4, arg5, arg6);
  1564	}
