  1618	FILE* fopen(const char* filename, const char* mode) {
  1619	    int flags = 0;
  1620	    int mode_val = 0644; /* Default permissions */
  1621	    
  1622	    /* Parse mode string */
  1623	    if (strchr(mode, 'r') != NULL) {
  1624	        flags = O_RDONLY;
  1625	        if (strchr(mode, '+') != NULL) {
  1626	            flags = O_RDWR;
  1627	        }
  1628	    } else if (strchr(mode, 'w') != NULL) {
  1629	        flags = O_WRONLY | O_CREAT | O_TRUNC;
  1630	        if (strchr(mode, '+') != NULL) {
  1631	            flags = O_RDWR | O_CREAT | O_TRUNC;
  1632	        }
  1633	    } else if (strchr(mode, 'a') != NULL) {
  1634	        flags = O_WRONLY | O_CREAT | O_APPEND;
  1635	        if (strchr(mode, '+') != NULL) {
  1636	            flags = O_RDWR | O_CREAT | O_APPEND;
  1637	        }
  1638	    } else {
  1639	        /* Invalid mode */
  1640	        errno = EINVAL;
  1641	    return NULL;
  1642	    }
  1643	
  1644	    /* Open the file using syscall */
  1645	    int fd = syscall3(SYS_open, filename, flags, mode_val);
  1646	    if (fd < 0) {
  1647	        return NULL;
  1648	    }
  1649	    
  1650	    /* Allocate FILE structure */
  1651	    FILE* file = (FILE*)malloc(sizeof(FILE));
  1652	    if (!file) {
  1653	        syscall1(SYS_close, fd);
  1654	        errno = ENOMEM;
  1655	        return NULL;
  1656	    }
  1657	    
  1658	    file->fd = fd;
  1659	    file->eof = 0;
  1660	    file->error = 0;
  1661	    file->position = 0;
  1662	    
  1663	    return file;
  1664	}
