  1678	size_t fread(void* ptr, size_t size, size_t nmemb, FILE* stream) {
  1679	    if (!stream || !ptr) {
  1680	        errno = EINVAL;
  1681	    return 0;
  1682	    }
  1683	    
  1684	    size_t bytes_to_read = size * nmemb;
  1685	    ssize_t bytes_read = syscall3(SYS_read, stream->fd, ptr, bytes_to_read);
  1686	    
  1687	    if (bytes_read < 0) {
  1688	        stream->error = 1;
  1689	        return 0;
  1690	    }
  1691	    
  1692	    if (bytes_read == 0 || bytes_read < bytes_to_read) {
  1693	        stream->eof = 1;
