  1771	int atoi(const char* nptr) {
  1772	    int result = 0;
  1773	    int sign = 1;
  1774	    
  1775	    /* Skip whitespace */
  1776	    while (*nptr == ' ' || *nptr == '\t' || *nptr == '\n' || *nptr == '\r') {
  1777	        nptr++;
  1778	    }
  1779	    
  1780	    /* Handle sign */
  1781	    if (*nptr == '-') {
  1782	        sign = -1;
  1783	        nptr++;
  1784	    } else if (*nptr == '+') {
  1785	        nptr++;
  1786	    }
  1787	    
  1788	    /* Convert digits */
  1789	    while (*nptr >= '0' && *nptr <= '9') {
  1790	        result = result * 10 + (*nptr - '0');
  1791	        nptr++;
  1792	    }
  1793	    
  1794	    return sign * result;
  1795	}
