405	// Check if the specified directory contains the specified IWAD
406	// file, returning the full path to the IWAD if found, or NULL
407	// if not found.
408	
409	static char *CheckDirectoryHasIWAD(char *dir, char *iwadname)
410	{
411	    char *filename; 
412	
413	    // As a special case, the "directory" may refer directly to an
414	    // IWAD file if the path comes from DOOMWADDIR or DOOMWADPATH.
415	
416	    if (DirIsFile(dir, iwadname) && M_FileExists(dir))
417	    {
418	        return strdup(dir);
419	    }
420	
421	    // Construct the full path to the IWAD if it is located in
422	    // this directory, and check if it exists.
423	
424	    if (!strcmp(dir, "."))
425	    {
426	        filename = strdup(iwadname);
427	    }
428	    else
429	    {
430	        filename = M_StringJoin(dir, DIR_SEPARATOR_S, iwadname, NULL);
431	    }
432	
433	    printf("Trying IWAD file:%s\n", filename);
434	
435	    if (M_FileExists(filename))
436	    {
437	        return filename;
438	    }
439	
440	    free(filename);
441	
442	    return NULL;
443	}
