448	static char *SearchDirectoryForIWAD(char *dir, int mask, GameMission_t *mission)
449	{
450	    char *filename;
451	    size_t i;
452	
453	    for (i=0; i<arrlen(iwads); ++i) 
454	    {
455	        if (((1 << iwads[i].mission) & mask) == 0)
456	        {
457	            continue;
458	        }
459	
460	        filename = CheckDirectoryHasIWAD(dir, DEH_String(iwads[i].name));
461	
