627	// 
628	
629	char *D_FindWADByName(char *name)
630	{
631	    char *path;
632	    int i;
633	    
634	    // Absolute path?
635	
636	    if (M_FileExists(name))
637	    {
638	        return name;
639	    }
640	
641	    BuildIWADDirList();
642	
643	    // Search through all IWAD paths for a file with the given name.
644	
645	    for (i=0; i<num_iwad_dirs; ++i)
646	    {
647	        // As a special case, if this is in DOOMWADDIR or DOOMWADPATH,
648	        // the "directory" may actually refer directly to an IWAD
649	        // file.
650	
651	        if (DirIsFile(iwad_dirs[i], name) && M_FileExists(iwad_dirs[i]))
652	        {
653	            return strdup(iwad_dirs[i]);
654	        }
655	
656	        // Construct a string for the full path
657	
658	        path = M_StringJoin(iwad_dirs[i], DIR_SEPARATOR_S, name, NULL);
659	
660	        if (M_FileExists(path))
661	        {
662	            return path;
663	        }
664	
665	        free(path);
666	    }
667	
668	    // File not found
669	
670	    return NULL;
671	}
