 87	//
 88	// Determine the length of an open file.
 89	//
 90	
 91	long M_FileLength(FILE *handle)
 92	{ 
 93	    long savedpos;
 94	    long length;
 95	
 96	    // save the current position in the file
 97	    savedpos = ftell(handle);
 98	    
 99	    // jump to the end and find the length
100	    fseek(handle, 0, SEEK_END);
101	    length = ftell(handle);
102	
103	    // go back to the old location
104	    fseek(handle, savedpos, SEEK_SET);
105	
106	    return length;
107	}
