199	void M_ExtractFileBase(char *path, char *dest)
200	{
201	    char *src;
202	    char *filename;
203	    int length;
204	
205	    src = path + strlen(path) - 1;
206	
207	    // back up until a \ or the start
208	    while (src != path && *(src - 1) != DIR_SEPARATOR)
209	    {
210		src--;
211	    }
212	
213	    filename = src;
214	
215	    // Copy up to eight characters
216	    // Note: Vanilla Doom exits with an error if a filename is specified
217	    // with a base of more than eight characters.  To remove the 8.3
218	    // filename limit, instead we simply truncate the name.
219	
220	    length = 0;
221	    memset(dest, 0, 8);
222	
223	    while (*src != '\0' && *src != '.')
224	    {
225	        if (length >= 8)
226	        {
227	            printf("Warning: Truncated '%s' lump name to '%.8s'.\n",
228	                   filename, dest);
229	            break;
230	        }
231	
232		dest[length++] = toupper((int)*src++);
233	    }
234	}
