257	// Case-insensitive version of strstr()
258	//
259	
260	char *M_StrCaseStr(char *haystack, char *needle)
261	{
262	    unsigned int haystack_len;
263	    unsigned int needle_len;
264	    unsigned int len;
265	    unsigned int i;
266	
267	    haystack_len = strlen(haystack);
268	    needle_len = strlen(needle);
269	
270	    if (haystack_len < needle_len)
271	    {
272	        return NULL;
273	    }
274	
275	    len = haystack_len - needle_len;
276	
277	    for (i = 0; i <= len; ++i)
278	    {
279	        if (!strncasecmp(haystack + i, needle, needle_len))
280	        {
281	            return haystack + i;
282	        }
283	    }
284	
285	    return NULL;
