313	                      const char *replacement)
314	{
315	    char *result, *dst;
316	    const char *p;
317	    size_t needle_len = strlen(needle);
318	    size_t result_len, dst_len;
319	
320	    // Iterate through occurrences of 'needle' and calculate the size of
321	    // the new string.
322	    result_len = strlen(haystack) + 1;
323	    p = haystack;
324	
325	    for (;;)
326	    {
327	        p = strstr(p, needle);
328	        if (p == NULL)
329	        {
330	            break;
331	        }
332	
333	        p += needle_len;
334	        result_len += strlen(replacement) - needle_len;
335	    }
336	
337	    // Construct new string.
338	
339	    result = malloc(result_len);
340	    if (result == NULL)
341	    {
342	        I_Error("M_StringReplace: Failed to allocate new string");
343	        return NULL;
344	    }
345	
346	    dst = result; dst_len = result_len;
347	    p = haystack;
