482	// Safe, portable vsnprintf().
483	int M_vsnprintf(char *buf, size_t buf_len, const char *s, va_list args)
484	{
485	    int result;
486	
487	    if (buf_len < 1)
488	    {
489	        return 0;
490	    }
491	
492	    // Windows (and other OSes?) has a vsnprintf() that doesn't always
493	    // append a trailing \0. So we must do it, and write into a buffer
494	    // that is one byte shorter; otherwise this function is unsafe.
495	    result = vsnprintf(buf, buf_len, s, args);
496	
497	    // If truncated, change the final char in the buffer to a \0.
498	    // A negative result indicates a truncated buffer on Windows.
499	    if (result < 0 || result >= buf_len)
500	    {
501	        buf[buf_len - 1] = '\0';
502	        result = buf_len - 1;
503	    }
504	
505	    return result;
506	}
